+// environmentVariableHookFunc replaces strings that consist entirely of a
+// ${VARIABLE_NAME} reference with the corresponding environment variable.
+func environmentVariableHookFunc() mapstructure.DecodeHookFunc {
+	return func(f reflect.Type, _ reflect.Type, data interface{}) (interface{}, error) {
+		if f.Kind() != reflect.String {
+			return data, nil
+		}
+
+		value := data.(string)
+		if len(value) < 4 || value[0] != '$' || value[1] != '{' || value[len(value)-1] != '}' {
+			return data, nil
+		}
+
+		name := value[2 : len(value)-1]
+		if name == "" {
+			return data, nil
+		}
+		for i, r := range name {
+			if !((r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || r == '_' || (i > 0 && r >= '0' && r <= '9')) {
+				return data, nil
+			}
+		}
+
+		if env, ok := os.LookupEnv(name); ok {
+			return env, nil
+		}
+		return data, nil
+	}
+}
